-- Estoque › Inventário aberto (CEO 13/10): textos do "?" dos campos novos (RD-95). Aditivo e idempotente.
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, 'Inventário', v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, '/dashboard/commerce/estoque', 'comercio', 'publicado'
FROM (VALUES
 ('estoque.inventario.incluir_zerados', 'Incluir itens zerados', 'Deixe marcado para que produtos ativos com saldo 0 também entrem na lista de contagem.', 'A contagem pode achar mercadoria que o sistema dá como zerada; sem o item na lista ela não teria onde ser registrada.', 'Espuma com saldo 0 e 3.000 na prateleira: entra e aparece como sobra de 3.000.', 'Desmarcar e depois não achar o produto para contar; nesse caso use Adicionar produto.', 1),
 ('estoque.inventario.subir_planilha', 'Subir planilha de contagem', 'Escolha o arquivo .xlsx baixado deste inventário e preenchido na coluna QUANTIDADE CONTADA.', 'Preenche a coluna Contado deste inventário de uma vez. Antes de gravar você vê a prévia; o estoque só muda em Fechar inventário.', 'Planilha com 45 linhas: 44 casadas e 1 fora do inventário.', 'Subir planilha de outro inventário ou com a linha de chaves alterada; baixe de novo a partir deste inventário.', 2),
 ('estoque.inventario.adicionar_fora', 'Adicionar produtos fora da lista', 'Marque para incluir no inventário os produtos contados na planilha que não estavam na lista.', 'Evita digitar à mão o que a contagem achou além da lista; o saldo do sistema entra como ponto de partida da diferença.', '2 produtos contados que não estavam na lista entram com a quantidade da planilha.', 'Deixar desmarcado e esquecer que esses itens ficaram sem contagem registrada.', 3),
 ('estoque.inventario.adicionar_item', 'Adicionar produto ao inventário', 'Digite 2 letras ou mais do nome, do código ou do código de barras e toque no produto.', 'Inclui no inventário aberto um produto que não estava na lista, para registrar a contagem dele.', 'Buscar "polipex" e tocar em Espuma Polipex 274.', 'Procurar produto inativo ou que já está na lista; esses não aparecem na busca.', 4),
 ('estoque.inventario.busca', 'Buscar na lista', 'Digite parte do nome, do código ou o código de barras (EAN).', 'Filtra a lista de itens do inventário na hora, sem alterar nenhuma contagem.', '7891234567895 mostra só o produto com esse EAN.', 'Achar que o item sumiu: confira se há outro filtro ativo.', 5),
 ('estoque.inventario.filtro', 'Filtro da lista', 'Escolha entre todos, só com divergência ou só não contados.', 'Mostra o que ainda precisa de atenção: itens contados com diferença ou itens que ninguém contou.', 'Só não contados (12) para saber o que falta.', 'Fechar o inventário sem olhar os não contados.', 6),
 ('estoque.inventario.ordem', 'Ordem da lista', 'Escolha ordenar por nome ou pela maior diferença em reais.', 'Ordenar por diferença coloca no topo o que mais pesa no valor do estoque, para conferir primeiro.', 'Diferença de R$ 1.200 aparece antes de uma de R$ 3.', 'Esperar que itens não contados apareçam no topo; eles não têm diferença ainda.', 7)
) AS v(chave, rotulo, o_que, para_que, exemplo, erro, ordem)
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'erp_ajuda_campo')
ON CONFLICT (chave) DO NOTHING;
